 {"id":"d4fdaf3c-52f3-4f4f-a743-c177caa59448","event_id":"00000000-0000-4000-8000-0000000de304","name":"Please clean the table","has_quantity":false,"is_active":true,"sort_order":4}]'::jsonb)
  ) v(ord, tbl, rows) order by ord loop
    if to_regclass('public.' || r.tbl) is null then continue; end if;
    -- only the columns this database has, and that the demo data has
    select string_agg(quote_ident(c.column_name), ', ' order by c.ordinal_position) into cols
      from information_schema.columns c
     where c.table_schema = 'public' and c.table_name = r.tbl and c.is_generated = 'NEVER'
       and exists (select 1 from jsonb_array_elements(r.rows) e where e ? c.column_name);
    if cols is null then continue; end if;
    execute format('insert into public.%I (%s) select %s from jsonb_populate_recordset(null::public.%I, $1) on conflict do nothing',
                   r.tbl, cols, cols, r.tbl) using r.rows;
  end loop;
  update public.events set date = (now() at time zone 'Asia/Kolkata')::date where id = ev;
end
